// Reviewed classical texts are public domain; definitions and ability programs are project-authored.
export const POEMS=[{"id":"poem-001","title":"咏鹅","author":"骆宾王","grade":"一年级上册","paragraphs":["鹅，鹅，鹅，曲项向天歌。","白毛浮绿水，红掌拨清波。"],"url":"https://www.gushiwenku.cn/shiwen/168f4f7/"},{"id":"poem-002","title":"江南","author":"汉乐府","grade":"一年级上册","paragraphs":["江南可采莲，莲叶何田田，鱼戏莲叶间。","鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。"],"url":"https://www.gushiwenku.cn/shiwen/824ac92/"},{"id":"poem-003","title":"画","author":"作者待考","grade":"一年级上册","paragraphs":["远看山有色，近听水无声。","春去花还在，人来鸟不惊。"],"note":"小学识字课文中的题画诗；作者归属存在不同说法。","url":"https://www.gushiwenku.cn/shiwen/ac411ec/"},{"id":"poem-004","title":"悯农·其二","author":"李绅","grade":"一年级上册","paragraphs":["锄禾日当午，汗滴禾下土。","谁知盘中餐，粒粒皆辛苦？"],"url":"https://www.gushiwenku.cn/shiwen/5f3cd93/"},{"id":"poem-005","title":"古朗月行（节选）","author":"李白","grade":"一年级上册","paragraphs":["小时不识月，呼作白玉盘。","又疑瑶台镜，飞在青云端。"],"url":"https://www.gushiwenku.cn/shiwen/9692c5e/"},{"id":"poem-006","title":"风","author":"李峤","grade":"一年级上册","paragraphs":["解落三秋叶，能开二月花。","过江千尺浪，入竹万竿斜。"],"url":"https://www.gushiwenku.cn/shiwen/3915bf2/"},{"id":"poem-007","title":"春晓","author":"孟浩然","grade":"一年级下册","paragraphs":["春眠不觉晓，处处闻啼鸟。","夜来风雨声，花落知多少。"],"url":"https://www.gushiwenku.cn/shiwen/9b62b46/"},{"id":"poem-008","title":"赠汪伦","author":"李白","grade":"一年级下册","paragraphs":["李白乘舟将欲行，忽闻岸上踏歌声。","桃花潭水深千尺，不及汪伦送我情。"],"url":"https://www.gushiwenku.cn/shiwen/abfc8be/"},{"id":"poem-009","title":"静夜思","author":"李白","grade":"一年级下册","paragraphs":["床前明月光，疑是地上霜。","举头望明月，低头思故乡。"],"url":"https://www.gushiwenku.cn/shiwen/f94de8e/"},{"id":"poem-010","title":"寻隐者不遇","author":"贾岛","grade":"一年级下册","paragraphs":["松下问童子，言师采药去。","只在此山中，云深不知处。"],"url":"https://www.gushiwenku.cn/shiwen/09c8974/"},{"id":"poem-011","title":"池上","author":"白居易","grade":"一年级下册","paragraphs":["小娃撑小艇，偷采白莲回。","不解藏踪迹，浮萍一道开。"],"url":"https://www.gushiwenku.cn/shiwen/6f2b477/"},{"id":"poem-012","title":"小池","author":"杨万里","grade":"一年级下册","paragraphs":["泉眼无声惜细流，树阴照水爱晴柔。","小荷才露尖尖角，早有蜻蜓立上头。"],"url":"https://www.gushiwenku.cn/shiwen/99847c1/"},{"id":"poem-013","title":"画鸡","author":"唐寅","grade":"一年级下册","paragraphs":["头上红冠不用裁，满身雪白走将来。","平生不敢轻言语，一叫千门万户开。"],"url":"https://www.gushiwenku.cn/shiwen/dece85d/"},{"id":"poem-014","title":"梅花","author":"王安石","grade":"二年级上册","paragraphs":["墙角数枝梅，凌寒独自开。","遥知不是雪，为有暗香来。"],"url":"https://www.gushiwenku.cn/shiwen/76d4ae1/"},{"id":"poem-015","title":"小儿垂钓","author":"胡令能","grade":"二年级上册","paragraphs":["蓬头稚子学垂纶，侧坐莓苔草映身。","路人借问遥招手，怕得鱼惊不应人。"],"url":"https://www.gushiwenku.cn/shiwen/1d8d6f1/"},{"id":"poem-016","title":"登鹳雀楼","author":"王之涣","grade":"二年级上册","paragraphs":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"url":"https://www.gushiwenku.cn/shiwen/6be1140/"},{"id":"poem-017","title":"望庐山瀑布","author":"李白","grade":"二年级上册","paragraphs":["日照香炉生紫烟，遥看瀑布挂前川。","飞流直下三千尺，疑是银河落九天。"],"url":"https://www.gushiwenku.cn/shiwen/eae33c6/"},{"id":"poem-018","title":"江雪","author":"柳宗元","grade":"二年级上册","paragraphs":["千山鸟飞绝，万径人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"url":"https://www.gushiwenku.cn/shiwen/689eacb/"},{"id":"poem-019","title":"夜宿山寺","author":"李白","grade":"二年级上册","paragraphs":["危楼高百尺，手可摘星辰。","不敢高声语，恐惊天上人。"],"url":"https://www.gushiwenku.cn/shiwen/3ceb10b/"},{"id":"poem-020","title":"敕勒歌","author":"佚名","grade":"二年级上册","paragraphs":["敕勒川，阴山下。","天似穹庐，笼盖四野。","天苍苍，野茫茫，风吹草低见牛羊。"],"url":"https://www.gushiwenku.cn/shiwen/9848deb/"},{"id":"poem-021","title":"村居","author":"高鼎","grade":"二年级下册","paragraphs":["草长莺飞二月天，拂堤杨柳醉春烟。","儿童散学归来早，忙趁东风放纸鸢。"],"url":"https://www.gushiwenku.cn/shiwen/2c39345/"},{"id":"poem-022","title":"咏柳","author":"贺知章","grade":"二年级下册","paragraphs":["碧玉妆成一树高，万条垂下绿丝绦。","不知细叶谁裁出，二月春风似剪刀。"],"url":"https://www.gushiwenku.cn/shiwen/4afec3e/"},{"id":"poem-023","title":"赋得古原草送别","author":"白居易","grade":"二年级下册","paragraphs":["离离原上草，一岁一枯荣。","野火烧不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孙去，萋萋满别情。"],"url":"https://www.gushiwenku.cn/shiwen/dca8ec0/"},{"id":"poem-024","title":"晓出净慈寺送林子方","author":"杨万里","grade":"二年级下册","paragraphs":["毕竟西湖六月中，风光不与四时同。","接天莲叶无穷碧，映日荷花别样红。"],"url":"https://www.gushiwenku.cn/shiwen/59b23b9/"},{"id":"poem-025","title":"绝句","author":"杜甫","grade":"二年级下册","paragraphs":["两个黄鹂鸣翠柳，一行白鹭上青天。","窗含西岭千秋雪，门泊东吴万里船。"],"url":"https://www.gushiwenku.cn/shiwen/25bfe6c/"},{"id":"poem-026","title":"悯农·其一","author":"李绅","grade":"二年级下册","paragraphs":["春种一粒粟，秋收万颗子。","四海无闲田，农夫犹饿死。"],"url":"https://www.gushiwenku.cn/shiwen/aebfdde/"},{"id":"poem-027","title":"舟夜书所见","author":"查慎行","grade":"二年级下册","paragraphs":["月黑见渔灯，孤光一点萤。","微微风簇浪，散作满河星。"],"url":"https://www.gushiwenku.cn/shiwen/6c93dc9/"},{"id":"poem-028","title":"所见","author":"袁枚","grade":"三年级上册","paragraphs":["牧童骑黄牛，歌声振林樾。","意欲捕鸣蝉，忽然闭口立。"],"url":"https://www.gushiwenku.cn/shiwen/18a13e2/"},{"id":"poem-029","title":"山行","author":"杜牧","grade":"三年级上册","paragraphs":["远上寒山石径斜，白云生处有人家。","停车坐爱枫林晚，霜叶红于二月花。"],"url":"https://www.gushiwenku.cn/shiwen/ac94142/"},{"id":"poem-030","title":"赠刘景文","author":"苏轼","grade":"三年级上册","paragraphs":["荷尽已无擎雨盖，菊残犹有傲霜枝。","一年好景君须记，最是橙黄橘绿时。"],"url":"https://www.gushiwenku.cn/shiwen/5d9b4ac/"},{"id":"poem-031","title":"夜书所见","author":"叶绍翁","grade":"三年级上册","paragraphs":["萧萧梧叶送寒声，江上秋风动客情。","知有儿童挑促织，夜深篱落一灯明。"],"url":"https://www.gushiwenku.cn/shiwen/2d2b50a/"},{"id":"poem-032","title":"望天门山","author":"李白","grade":"三年级上册","paragraphs":["天门中断楚江开，碧水东流至此回。","两岸青山相对出，孤帆一片日边来。"],"url":"https://www.gushiwenku.cn/shiwen/37713ed/"},{"id":"poem-033","title":"饮湖上初晴后雨","author":"苏轼","grade":"三年级上册","paragraphs":["水光潋滟晴方好，山色空蒙雨亦奇。","欲把西湖比西子，淡妆浓抹总相宜。"],"url":"https://www.gushiwenku.cn/shiwen/02cdcab/"},{"id":"poem-034","title":"望洞庭","author":"刘禹锡","grade":"三年级上册","paragraphs":["湖光秋月两相和，潭面无风镜未磨。","遥望洞庭山水翠，白银盘里一青螺。"],"url":"https://www.gushiwenku.cn/shiwen/8a92bb1/"},{"id":"poem-035","title":"早发白帝城","author":"李白","grade":"三年级上册","paragraphs":["朝辞白帝彩云间，千里江陵一日还。","两岸猿声啼不住，轻舟已过万重山。"],"url":"https://www.gushiwenku.cn/shiwen/d0c2932/"},{"id":"poem-036","title":"采莲曲","author":"王昌龄","grade":"三年级上册","paragraphs":["荷叶罗裙一色裁，芙蓉向脸两边开。","乱入池中看不见，闻歌始觉有人来。"],"url":"https://www.gushiwenku.cn/shiwen/551211f/"},{"id":"poem-037","title":"绝句·迟日江山丽","author":"杜甫","grade":"三年级下册","paragraphs":["迟日江山丽，春风花草香。","泥融飞燕子，沙暖睡鸳鸯。"],"url":"https://www.gushiwenku.cn/shiwen/67d931b/"},{"id":"poem-038","title":"惠崇春江晚景","author":"苏轼","grade":"三年级下册","paragraphs":["竹外桃花三两枝，春江水暖鸭先知。","蒌蒿满地芦芽短，正是河豚欲上时。"],"url":"https://www.gushiwenku.cn/shiwen/4443f41/"},{"id":"poem-039","title":"三衢道中","author":"曾几","grade":"三年级下册","paragraphs":["梅子黄时日日晴，小溪泛尽却山行。","绿阴不减来时路，添得黄鹂四五声。"],"url":"https://www.gushiwenku.cn/shiwen/ba4a309/"},{"id":"poem-040","title":"忆江南·江南好","author":"白居易","grade":"三年级下册","paragraphs":["江南好，风景旧曾谙。","日出江花红胜火，春来江水绿如蓝。能不忆江南？"],"url":"https://www.gushiwenku.cn/shiwen/9669172/"},{"id":"poem-041","title":"元日","author":"王安石","grade":"三年级下册","paragraphs":["爆竹声中一岁除，春风送暖入屠苏。","千门万户曈曈日，总把新桃换旧符。"],"url":"https://www.gushiwenku.cn/shiwen/dcb4593/"},{"id":"poem-042","title":"清明","author":"杜牧","grade":"三年级下册","paragraphs":["清明时节雨纷纷，路上行人欲断魂。","借问酒家何处有？牧童遥指杏花村。"],"url":"https://www.gushiwenku.cn/shiwen/5f6d468/"},{"id":"poem-043","title":"九月九日忆山东兄弟","author":"王维","grade":"三年级下册","paragraphs":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"url":"https://www.gushiwenku.cn/shiwen/13a36a1/"},{"id":"poem-044","title":"滁州西涧","author":"韦应物","grade":"三年级下册","paragraphs":["独怜幽草涧边生，上有黄鹂深树鸣。","春潮带雨晚来急，野渡无人舟自横。"],"url":"https://www.gushiwenku.cn/shiwen/d59b33d/"},{"id":"poem-045","title":"大林寺桃花","author":"白居易","grade":"三年级下册","paragraphs":["人间四月芳菲尽，山寺桃花始盛开。","长恨春归无觅处，不知转入此中来。"],"url":"https://www.gushiwenku.cn/shiwen/2617f2b/"},{"id":"poem-046","title":"鹿柴","author":"王维","grade":"四年级上册","paragraphs":["空山不见人，但闻人语响。","返景入深林，复照青苔上。"],"url":"https://www.gushiwenku.cn/shiwen/8f82b5d/"},{"id":"poem-047","title":"暮江吟","author":"白居易","grade":"四年级上册","paragraphs":["一道残阳铺水中，半江瑟瑟半江红。","可怜九月初三夜，露似真珠月似弓。"],"url":"https://www.gushiwenku.cn/shiwen/bad340c/"},{"id":"poem-048","title":"题西林壁","author":"苏轼","grade":"四年级上册","paragraphs":["横看成岭侧成峰，远近高低各不同。","不识庐山真面目，只缘身在此山中。"],"url":"https://www.gushiwenku.cn/shiwen/f0964ed/"},{"id":"poem-049","title":"雪梅","author":"卢钺","grade":"四年级上册","paragraphs":["梅雪争春未肯降，骚人阁笔费评章。","梅须逊雪三分白，雪却输梅一段香。"],"url":"https://www.gushiwenku.cn/shiwen/13e0eb2/"},{"id":"poem-050","title":"嫦娥","author":"李商隐","grade":"四年级上册","paragraphs":["云母屏风烛影深，长河渐落晓星沉。","嫦娥应悔偷灵药，碧海青天夜夜心。"],"url":"https://www.gushiwenku.cn/shiwen/b341c34/"},{"id":"poem-051","title":"出塞","author":"王昌龄","grade":"四年级上册","paragraphs":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"url":"https://www.gushiwenku.cn/shiwen/06105e4/"},{"id":"poem-052","title":"凉州词","author":"王翰","grade":"四年级上册","paragraphs":["葡萄美酒夜光杯，欲饮琵琶马上催。","醉卧沙场君莫笑，古来征战几人回？"],"url":"https://www.gushiwenku.cn/shiwen/049a59e/"},{"id":"poem-053","title":"夏日绝句","author":"李清照","grade":"四年级上册","paragraphs":["生当作人杰，死亦为鬼雄。","至今思项羽，不肯过江东。"],"url":"https://www.gushiwenku.cn/shiwen/f2c11ce/"},{"id":"poem-054","title":"别董大","author":"高适","grade":"四年级上册","paragraphs":["千里黄云白日曛，北风吹雁雪纷纷。","莫愁前路无知己，天下谁人不识君。"],"url":"https://www.gushiwenku.cn/shiwen/b4189d1/"},{"id":"poem-055","title":"宿新市徐公店","author":"杨万里","grade":"四年级下册","paragraphs":["篱落疏疏一径深，树头新绿未成阴。","儿童急走追黄蝶，飞入菜花无处寻。"],"url":"https://www.gushiwenku.cn/shiwen/2dd2173/"},{"id":"poem-056","title":"四时田园杂兴·其二十五","author":"范成大","grade":"四年级下册","paragraphs":["梅子金黄杏子肥，麦花雪白菜花稀。","日长篱落无人过，惟有蜻蜓蛱蝶飞。"],"url":"https://www.gushiwenku.cn/shiwen/4153bfc/"},{"id":"poem-057","title":"清平乐·村居","author":"辛弃疾","grade":"四年级下册","paragraphs":["茅檐低小，溪上青青草。醉里吴音相媚好，白发谁家翁媪？","大儿锄豆溪东，中儿正织鸡笼。最喜小儿亡赖，溪头卧剥莲蓬。"],"url":"https://www.gushiwenku.cn/shiwen/10b8c3d/"},{"id":"poem-058","title":"蜂","author":"罗隐","grade":"四年级下册","paragraphs":["不论平地与山尖，无限风光尽被占。","采得百花成蜜后，为谁辛苦为谁甜？"],"url":"https://www.gushiwenku.cn/shiwen/bb0e829/"},{"id":"poem-059","title":"独坐敬亭山","author":"李白","grade":"四年级下册","paragraphs":["众鸟高飞尽，孤云独去闲。","相看两不厌，只有敬亭山。"],"url":"https://www.gushiwenku.cn/shiwen/7c55426/"},{"id":"poem-060","title":"芙蓉楼送辛渐","author":"王昌龄","grade":"四年级下册","paragraphs":["寒雨连江夜入吴，平明送客楚山孤。","洛阳亲友如相问，一片冰心在玉壶。"],"url":"https://www.gushiwenku.cn/shiwen/c716520/"},{"id":"poem-061","title":"塞下曲","author":"卢纶","grade":"四年级下册","paragraphs":["月黑雁飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"],"url":"https://www.gushiwenku.cn/shiwen/b7eae90/"},{"id":"poem-062","title":"墨梅","author":"王冕","grade":"四年级下册","paragraphs":["我家洗砚池头树，朵朵花开淡墨痕。","不要人夸好颜色，只留清气满乾坤。"],"note":"采用小学常见教材写法；吾家、个个、只流等另有版本。","url":"https://www.gushiwenku.cn/shiwen/f38e404/"},{"id":"poem-063","title":"乞巧","author":"林杰","grade":"五年级上册","paragraphs":["七夕今宵看碧霄，牵牛织女渡河桥。","家家乞巧望秋月，穿尽红丝几万条。"],"url":"https://www.gushiwenku.cn/shiwen/cdf026c/"},{"id":"poem-064","title":"示儿","author":"陆游","grade":"五年级上册","paragraphs":["死去元知万事空，但悲不见九州同。","王师北定中原日，家祭无忘告乃翁。"],"url":"https://www.gushiwenku.cn/shiwen/30a881c/"},{"id":"poem-065","title":"题临安邸","author":"林升","grade":"五年级上册","paragraphs":["山外青山楼外楼，西湖歌舞几时休？","暖风熏得游人醉，直把杭州作汴州。"],"url":"https://www.gushiwenku.cn/shiwen/031b119/"},{"id":"poem-066","title":"己亥杂诗","author":"龚自珍","grade":"五年级上册","paragraphs":["九州生气恃风雷，万马齐喑究可哀。","我劝天公重抖擞，不拘一格降人才。"],"url":"https://www.gushiwenku.cn/shiwen/172078f/"},{"id":"poem-067","title":"山居秋暝","author":"王维","grade":"五年级上册","paragraphs":["空山新雨后，天气晚来秋。","明月松间照，清泉石上流。","竹喧归浣女，莲动下渔舟。","随意春芳歇，王孙自可留。"],"url":"https://www.gushiwenku.cn/shiwen/440dd75/"},{"id":"poem-068","title":"枫桥夜泊","author":"张继","grade":"五年级上册","paragraphs":["月落乌啼霜满天，江枫渔火对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"url":"https://www.gushiwenku.cn/shiwen/4d77ffc/"},{"id":"poem-069","title":"长相思·山一程","author":"纳兰性德","grade":"五年级上册","paragraphs":["山一程，水一程，身向榆关那畔行，夜深千帐灯。","风一更，雪一更，聒碎乡心梦不成，故园无此声。"],"url":"https://www.gushiwenku.cn/shiwen/7029835/"},{"id":"poem-070","title":"渔歌子·西塞山前白鹭飞","author":"张志和","grade":"五年级上册","paragraphs":["西塞山前白鹭飞，桃花流水鳜鱼肥。","青箬笠，绿蓑衣，斜风细雨不须归。"],"url":"https://www.gushiwenku.cn/shiwen/84a494f/"},{"id":"poem-071","title":"观书有感二首·其一","author":"朱熹","grade":"五年级上册","paragraphs":["半亩方塘一鉴开，天光云影共徘徊。","问渠那得清如许？为有源头活水来。"],"url":"https://www.gushiwenku.cn/shiwen/943ac55/"},{"id":"poem-072","title":"观书有感二首·其二","author":"朱熹","grade":"五年级上册","paragraphs":["昨夜江边春水生，艨艟巨舰一毛轻。","向来枉费推移力，此日中流自在行。"],"url":"https://www.gushiwenku.cn/shiwen/640172c/"},{"id":"poem-073","title":"四时田园杂兴·其三十一","author":"范成大","grade":"五年级下册","paragraphs":["昼出耘田夜绩麻，村庄儿女各当家。","童孙未解供耕织，也傍桑阴学种瓜。"],"url":"https://www.gushiwenku.cn/shiwen/1336a1a/"},{"id":"poem-074","title":"稚子弄冰","author":"杨万里","grade":"五年级下册","paragraphs":["稚子金盆脱晓冰，彩丝穿取当银钲。","敲成玉磬穿林响，忽作玻璃碎地声。"],"url":"https://www.gushiwenku.cn/shiwen/eb50dd5/"},{"id":"poem-075","title":"村晚","author":"雷震","grade":"五年级下册","paragraphs":["草满池塘水满陂，山衔落日浸寒漪。","牧童归去横牛背，短笛无腔信口吹。"],"url":"https://www.gushiwenku.cn/shiwen/953cfcb/"},{"id":"poem-076","title":"鸟鸣涧","author":"王维","grade":"五年级下册","paragraphs":["人闲桂花落，夜静春山空。","月出惊山鸟，时鸣春涧中。"],"url":"https://www.gushiwenku.cn/shiwen/0a0cf85/"},{"id":"poem-077","title":"从军行","author":"王昌龄","grade":"五年级下册","paragraphs":["青海长云暗雪山，孤城遥望玉门关。","黄沙百战穿金甲，不破楼兰终不还。"],"url":"https://www.gushiwenku.cn/shiwen/aaad75e/"},{"id":"poem-078","title":"送元二使安西","author":"王维","grade":"五年级下册","paragraphs":["渭城朝雨浥轻尘，客舍青青柳色新。","劝君更尽一杯酒，西出阳关无故人。"],"url":"https://www.gushiwenku.cn/shiwen/0355f9b/"},{"id":"poem-079","title":"秋夜将晓出篱门迎凉有感","author":"陆游","grade":"五年级下册","paragraphs":["三万里河东入海，五千仞岳上摩天。","遗民泪尽胡尘里，南望王师又一年。"],"url":"https://www.gushiwenku.cn/shiwen/2bb4287/"},{"id":"poem-080","title":"凉州词","author":"王之涣","grade":"五年级下册","paragraphs":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春风不度玉门关。"],"url":"https://www.gushiwenku.cn/shiwen/d0ad9af/"},{"id":"poem-081","title":"黄鹤楼送孟浩然之广陵","author":"李白","grade":"五年级下册","paragraphs":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧空尽，唯见长江天际流。"],"url":"https://www.gushiwenku.cn/shiwen/3d4e45f/"},{"id":"poem-082","title":"乡村四月","author":"翁卷","grade":"五年级下册","paragraphs":["绿遍山原白满川，子规声里雨如烟。","乡村四月闲人少，才了蚕桑又插田。"],"url":"https://www.gushiwenku.cn/shiwen/8f39357/"},{"id":"poem-083","title":"宿建德江","author":"孟浩然","grade":"六年级上册","paragraphs":["移舟泊烟渚，日暮客愁新。","野旷天低树，江清月近人。"],"url":"https://www.gushiwenku.cn/shiwen/cb40448/"},{"id":"poem-084","title":"六月二十七日望湖楼醉书","author":"苏轼","grade":"六年级上册","paragraphs":["黑云翻墨未遮山，白雨跳珠乱入船。","卷地风来忽吹散，望湖楼下水如天。"],"url":"https://www.gushiwenku.cn/shiwen/2243dbc/"},{"id":"poem-085","title":"西江月·夜行黄沙道中","author":"辛弃疾","grade":"六年级上册","paragraphs":["明月别枝惊鹊，清风半夜鸣蝉。稻花香里说丰年，听取蛙声一片。","七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。"],"url":"https://www.gushiwenku.cn/shiwen/39f9dfd/"},{"id":"poem-086","title":"过故人庄","author":"孟浩然","grade":"六年级上册","paragraphs":["故人具鸡黍，邀我至田家。","绿树村边合，青山郭外斜。","开轩面场圃，把酒话桑麻。","待到重阳日，还来就菊花。"],"url":"https://www.gushiwenku.cn/shiwen/ec01946/"},{"id":"poem-087","title":"春日","author":"朱熹","grade":"六年级上册","paragraphs":["胜日寻芳泗水滨，无边光景一时新。","等闲识得东风面，万紫千红总是春。"],"url":"https://www.gushiwenku.cn/shiwen/79f81b0/"},{"id":"poem-088","title":"回乡偶书","author":"贺知章","grade":"六年级上册","paragraphs":["少小离家老大回，乡音无改鬓毛衰。","儿童相见不相识，笑问客从何处来。"],"url":"https://www.gushiwenku.cn/shiwen/7d5de42/"},{"id":"poem-089","title":"浪淘沙·九曲黄河万里沙","author":"刘禹锡","grade":"六年级上册","paragraphs":["九曲黄河万里沙，浪淘风簸自天涯。","如今直上银河去，同到牵牛织女家。"],"url":"https://www.gushiwenku.cn/shiwen/c319c0c/"},{"id":"poem-090","title":"江南春","author":"杜牧","grade":"六年级上册","paragraphs":["千里莺啼绿映红，水村山郭酒旗风。","南朝四百八十寺，多少楼台烟雨中。"],"url":"https://www.gushiwenku.cn/shiwen/5b9dfb4/"},{"id":"poem-091","title":"书湖阴先生壁","author":"王安石","grade":"六年级上册","paragraphs":["茅檐长扫净无苔，花木成畦手自栽。","一水护田将绿绕，两山排闼送青来。"],"url":"https://www.gushiwenku.cn/shiwen/1d8462f/"},{"id":"poem-092","title":"寒食","author":"韩翃","grade":"六年级下册","paragraphs":["春城无处不飞花，寒食东风御柳斜。","日暮汉宫传蜡烛，轻烟散入五侯家。"],"url":"https://www.gushiwenku.cn/shiwen/1c5f8f2/"},{"id":"poem-093","title":"迢迢牵牛星","author":"佚名","grade":"六年级下册","paragraphs":["迢迢牵牛星，皎皎河汉女。","纤纤擢素手，札札弄机杼。","终日不成章，泣涕零如雨。","河汉清且浅，相去复几许？","盈盈一水间，脉脉不得语。"],"url":"https://www.gushiwenku.cn/shiwen/0ff14e0/"},{"id":"poem-094","title":"十五夜望月","author":"王建","grade":"六年级下册","paragraphs":["中庭地白树栖鸦，冷露无声湿桂花。","今夜月明人尽望，不知秋思落谁家？"],"url":"https://www.gushiwenku.cn/shiwen/4624da8/"},{"id":"poem-095","title":"长歌行","author":"汉乐府","grade":"六年级下册","paragraphs":["青青园中葵，朝露待日晞。","阳春布德泽，万物生光辉。","常恐秋节至，焜黄华叶衰。","百川东到海，何时复西归？","少壮不努力，老大徒伤悲。"],"url":"https://www.gushiwenku.cn/shiwen/092a59c/"},{"id":"poem-096","title":"马诗","author":"李贺","grade":"六年级下册","paragraphs":["大漠沙如雪，燕山月似钩。","何当金络脑，快走踏清秋。"],"url":"https://www.gushiwenku.cn/shiwen/1c6def1/"},{"id":"poem-097","title":"石灰吟","author":"于谦","grade":"六年级下册","paragraphs":["千锤万凿出深山，烈火焚烧若等闲。","粉骨碎身浑不怕，要留清白在人间。"],"url":"https://www.gushiwenku.cn/shiwen/c48280d/"},{"id":"poem-098","title":"竹石","author":"郑燮","grade":"六年级下册","paragraphs":["咬定青山不放松，立根原在破岩中。","千磨万击还坚劲，任尔东西南北风。"],"url":"https://www.gushiwenku.cn/shiwen/327f0ca/"},{"id":"poem-099","title":"春夜喜雨","author":"杜甫","grade":"六年级下册","paragraphs":["好雨知时节，当春乃发生。","随风潜入夜，润物细无声。","野径云俱黑，江船火独明。","晓看红湿处，花重锦官城。"],"url":"https://www.gushiwenku.cn/shiwen/b29f7ab/"},{"id":"poem-100","title":"闻官军收河南河北","author":"杜甫","grade":"六年级下册","paragraphs":["剑外忽传收蓟北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌须纵酒，青春作伴好还乡。","即从巴峡穿巫峡，便下襄阳向洛阳。"],"url":"https://www.gushiwenku.cn/shiwen/8ff9e79/"},{"id":"poem-101","title":"早春呈水部张十八员外","author":"韩愈","grade":"六年级下册","paragraphs":["天街小雨润如酥，草色遥看近却无。","最是一年春好处，绝胜烟柳满皇都。"],"url":"https://www.gushiwenku.cn/shiwen/ee0b85f/"},{"id":"poem-102","title":"江上渔者","author":"范仲淹","grade":"六年级下册","paragraphs":["江上往来人，但爱鲈鱼美。","君看一叶舟，出没风波里。"],"url":"https://www.gushiwenku.cn/shiwen/bc58add/"},{"id":"poem-103","title":"泊船瓜洲","author":"王安石","grade":"六年级下册","paragraphs":["京口瓜洲一水间，钟山只隔数重山。","春风又绿江南岸，明月何时照我还？"],"url":"https://www.gushiwenku.cn/shiwen/4f4460b/"},{"id":"poem-104","title":"游园不值","author":"叶绍翁","grade":"六年级下册","paragraphs":["应怜屐齿印苍苔，小扣柴扉久不开。","春色满园关不住，一枝红杏出墙来。"],"url":"https://www.gushiwenku.cn/shiwen/7845ffa/"},{"id":"poem-105","title":"卜算子·送鲍浩然之浙东","author":"王观","grade":"六年级下册","paragraphs":["水是眼波横，山是眉峰聚。欲问行人去那边，眉眼盈盈处。","才始送春归，又送君归去。若到江南赶上春，千万和春住。"],"url":"https://www.gushiwenku.cn/shiwen/f3135f7/"},{"id":"poem-106","title":"浣溪沙·游蕲水清泉寺","author":"苏轼","grade":"六年级下册","paragraphs":["山下兰芽短浸溪，松间沙路净无泥。萧萧暮雨子规啼。","谁道人生无再少，门前流水尚能西。休将白发唱黄鸡。"],"url":"https://www.gushiwenku.cn/shiwen/48abcc8/"},{"id":"poem-107","title":"清平乐·春归何处","author":"黄庭坚","grade":"六年级下册","paragraphs":["春归何处？寂寞无行路。若有人知春去处，唤取归来同住。","春无踪迹谁知？除非问取黄鹂。百啭无人能解，因风飞过蔷薇。"],"url":"https://www.gushiwenku.cn/shiwen/158b3ab/"},{"id":"poem-108","title":"如梦令·常记溪亭日暮","author":"李清照","grade":"常见课外","paragraphs":["常记溪亭日暮，沉醉不知归路。","兴尽晚回舟，误入藕花深处。","争渡，争渡，惊起一滩鸥鹭。"],"note":"常见课外补充，保留完整句界，不拼接不同诗篇。"},{"id":"poem-109","title":"田园乐·其六","author":"王维","grade":"常见课外","paragraphs":["桃红复含宿雨，柳绿更带朝烟。","花落家童未扫，莺啼山客犹眠。"],"note":"常见课外补充，保留完整句界，不拼接不同诗篇。"}];
